/**
 * Writes `pipeline/built-in-asset-types.ts`, the types a session with no
 * readable host classification reads as opaque (spec §2.2 A8), from the Vite
 * version Animus tests against: Vite's known asset types, `svg` included, and
 * its CSS languages. An SVGR-style plugin's `svg` module imports only its
 * renderer, the JS-bodied asset risk A8 accepts.
 *
 * Usage: node packages/extract/scripts/built-in-asset-types.ts --write
 *        node packages/extract/scripts/built-in-asset-types.ts --check
 *
 * `--check` writes nothing: it exits non-zero when the generated file holds
 * another list, or another Vite version, than the installed Vite's.
 */
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, unlinkSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

import { checkFormatterRun } from './css-keywords.ts';

const ROOT = join(import.meta.dirname, '../../..');
const OUTPUT = join(ROOT, 'packages/extract/pipeline/built-in-asset-types.ts');
const CHECK = join(
  ROOT,
  'packages/extract/pipeline/built-in-asset-types.check.ts'
);

/** The installed Vite's version, its `KNOWN_ASSET_TYPES` and the languages
 *  of its `CSS_LANGS_RE`, as its node bundle declares them. */
function viteAssetTypes() {
  const require = createRequire(
    join(ROOT, 'packages/vite-plugin/package.json')
  );
  const manifest = require.resolve('vite/package.json');
  const { version } = JSON.parse(readFileSync(manifest, 'utf8'));
  const chunks = join(dirname(manifest), 'dist/node/chunks');
  for (const name of readdirSync(chunks)) {
    const source = readFileSync(join(chunks, name), 'utf8');
    const declared = /const KNOWN_ASSET_TYPES = \[([^\]]*)\]/.exec(source);
    const languages = /const CSS_LANGS_RE = \/\\\.\(([a-z|]+)\)/.exec(source);
    if (declared === null || languages === null) continue;
    const types = [...declared[1].matchAll(/"([^"]+)"/g)].map(
      (match) => match[1]
    );
    return { version, types, stylesheets: languages[1].split('|') };
  }
  throw new Error(
    `vite@${version} declares no KNOWN_ASSET_TYPES and CSS_LANGS_RE in one chunk of ${chunks}`
  );
}

function generated(): string {
  const { version, types, stylesheets } = viteAssetTypes();
  return `// Generated by packages/extract/scripts/built-in-asset-types.ts from
// vite@${version}'s KNOWN_ASSET_TYPES and CSS_LANGS_RE. Do not edit.

/** The Vite version the built-in types come from. */
export const BUILT_IN_ASSET_SOURCE = 'vite@${version}';

/** Asset extensions, as regular-expression alternatives, a session with no
 *  readable host classification reads as assets (spec §2.2 A8). */
export const BUILT_IN_ASSET_TYPES = ${JSON.stringify(types)} as const;

/** Stylesheet extensions, as regular-expression alternatives, a session
 *  with no readable host classification reads as stylesheets. */
export const BUILT_IN_STYLESHEET_TYPES = ${JSON.stringify(stylesheets)} as const;
`;
}

if (process.argv.includes('--write')) {
  writeFileSync(OUTPUT, generated());
  // The committed bytes are the repository formatter's layout.
  checkFormatterRun(
    spawnSync(join(ROOT, 'node_modules/.bin/vp'), ['fmt', OUTPUT], {
      cwd: ROOT,
      encoding: 'utf8',
    })
  );
}

if (process.argv.includes('--check')) {
  writeFileSync(CHECK, generated());
  checkFormatterRun(
    spawnSync(join(ROOT, 'node_modules/.bin/vp'), ['fmt', CHECK], {
      cwd: ROOT,
      encoding: 'utf8',
    })
  );
  const expected = readFileSync(CHECK, 'utf8');
  unlinkSync(CHECK);
  if (readFileSync(OUTPUT, 'utf8') !== expected) {
    process.stderr.write(
      'built-in-asset-types.ts differs from the installed Vite. Regenerate it: ' +
        'node packages/extract/scripts/built-in-asset-types.ts --write\n'
    );
    process.exit(1);
  }
}
